function validate([day, month, year]) {
  if (![day, month, year].every(Number.isInteger)) return 'day, month and year must be whole numbers.';
  if (year < 1971 || year > 2100) return 'year is between 1971 and 2100.';
  if (month < 1 || month > 12) return 'month is between 1 and 12.';
  const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const last = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][month - 1];
  if (day < 1 || day > last) return 'That month does not have that day.';
  return null;
}

