  const pick = (n) => Math.floor(rand() * n);
  const isLeap = (y) => (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
  const lengthOf = (m, y) => [31, isLeap(y) ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][m - 1];
  const special = [1971, 1972, 2000, 2096, 2099, 2100];
  const year = size === 'small' && rand() < 0.4 ? special[pick(special.length)] : 1971 + pick(130);
  const month = size === 'small' && rand() < 0.3 ? [1, 2, 3, 12][pick(4)] : 1 + pick(12);
  const last = lengthOf(month, year);
  const day = rand() < 0.25 ? (rand() < 0.5 ? 1 : last) : 1 + pick(last);
  return [day, month, year];
}
